            }
#endif
        }
        if(s->cancelled)throw std::runtime_error("Cancelled");
        phase=2;
        s->model = llama_model_load_from_file(filename.c_str(), p);
        if(s->cancelled){if(s->model){llama_model_free(s->model);s->model=nullptr;}throw std::runtime_error("Cancelled");}
